 "content": "def transform(grid):
    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])
    # The colored object sits adjacent to a full-length directional guide;
    # extend a contrasting line immediately beyond the object in that direction.
    guides = [(r, c) for r in range(h) for c in range(w) if g[r][c] not in (1, 9)]
    if guides:
        colors = {g[r][c] for r, c in guides}
        guide_color = max(colors, key=lambda x: sum(g[r][c] == x for r, c in guides))
        if all(any(g[r][c] == guide_color for c in range(w)) for r in range(h)):
            # Vertical guide: place line at the first empty column after object.
            cols = [c for r in range(h) for c in range(w) if g[r][c] == 9]
            target = max(cols) + 1
            if target < w:
                for r in range(h): g[r][target] = 8
        else:
            rows = [r for r in range(h) for c in range(w) if g[r][c] not in (1, guide_color)]
            target = max(rows) + 1
            if target < h:
                for c in range(w): g[target][c] = 8
    return g
